; [GameState] Handles game mode transitions, checks $00C9 and $056C flags
HandleGameModeTransition:
        PHB
        PHP
        PHK
        PLB
        SEP #$20
        REP #$10
        LDA.W $00C9
        BNE CheckGameModeFlags
        JSR.W UpdateMusicTempo
; [GameState] Checks game mode flags and sets mode to $0C if conditions met
CheckGameModeFlags:
        REP #$30
        LDA.W $056C
        BIT.W #$1000
        BEQ ContinueGameModeProcessing
        SEP #$20
        LDA.W $00D4
        ORA.W $00D5
        BNE ContinueGameModeProcessing
        STZ.W $0081
        LDA.B #$0C
        STA.W $00C8
        STZ.W $00C9
        JSL.L InitAudioController
        PLP
        PLB
        RTL
; [GameState] Continues game mode processing after flag checks
ContinueGameModeProcessing:
        SEP #$20
        LDA.W $056D
        BIT.B #$80
        BEQ ProcessSpriteGraphics
        INC.W $12C4
        INC.W $12C4
        LDA.W $12C4
        CMP.B #$3E
        BNE LoadSpriteData
        STZ.W $12C4
; [OAM] Loads sprite data from table at $868000 based on $12C4
LoadSpriteData:
        JSR.W UpdateAudioRegisters
; [OAM] Processes sprite graphics data after loading
ProcessSpriteGraphics:
        JSR.W CheckSoundPriority
        REP #$20
        SEP #$10
        LDA.W $12C4
        AND.W #$00FF
        ASL A
        TAX
        LDA.L $868000,X
        STA.B $10
        SEP #$20
        LDA.L $868002,X
        STA.B $12
        REP #$30
        LDA.B [$10]
        STA.W $0000
