        STA.B $10
        LDA.W #$007E
        STA.B $12
        LDX.W #$0060
; [Text] Clears text buffer at $7E2000 with spaces ($2020). Entry: X=buffer size/offset.
ClearTextBuffer:
        LDA.W #$2020
        STA.L $7E2000,X
        DEX
        DEX
        BNE ClearTextBuffer
        LDY.W #$0000
        TYX
        SEP #$20
; [Text] Copies text string from [$10],Y to buffer until $FF terminator
CopyTextString:
        LDA.B [$10],Y
        CMP.B #$FF
        BEQ SetupTextRendering
        STA.L $7E2000,X
        LDA.B #$20
        STA.L $7E2001,X
        INX
        INX
        INY
        BRA CopyTextString
; [Text] Sets up text rendering after string copy
SetupTextRendering:
        REP #$20
        LDX.W $0F22
; [Text] Loads text data from table at $81CE to $0E22 buffer
LoadTextData:
        LDA.W $81CE,X
        CMP.W #$FFFF
