; [Entity] Processes game entities/objects. Checks $00FA flag, processes entities based on $0F26 state.
ProcessGameEntities:
        PHB
        PHP
        PHK
        PLB
        PHD
        REP #$30
        JSR.W ProcessEntityBlocks
        LDA.W $00FA
        AND.W #$00FF
        BEQ ProcessEntityGroup1
        PLD
        PLP
        PLB
        RTL
; [Entity] Processes entity group 1 (entities at $0600-$0A00). Calls ProcessEntityGroup for each entity slot.
ProcessEntityGroup1:
        LDA.W $0F26
        AND.W #$0003
        CMP.W #$0001
        BNE ProcessSecondaryEntities
        LDA.W #$0600
        TCD
        JSR.W ProcessEntityGroup
        LDA.W #$0700
        TCD
        JSR.W ProcessEntityGroup
        LDA.W #$0800
        TCD
        JSR.W ProcessEntityGroup
        LDA.W #$0900
        TCD
        JSR.W ProcessEntityGroup
        LDA.W #$0A00
        TCD
        JSR.W ProcessEntityGroup
; [Entity] Processes secondary entity group. Similar to ProcessGameEntities but for different entity type.
ProcessSecondaryEntities:
        LDA.W $0F26
        AND.W #$0003
        CMP.W #$0002
        BNE ReturnFromScript
        LDA.W #$0600
        TCD
        JSR.W ProcessGraphicsUpdate
        LDA.W #$0700
        TCD
        JSR.W ProcessGraphicsUpdate
        LDA.W #$0800
        TCD
        JSR.W ProcessGraphicsUpdate
        LDA.W #$0900
        TCD
        JSR.W ProcessGraphicsUpdate
        LDA.W #$0A00
        TCD
        JSR.W ProcessGraphicsUpdate
; [Script] Returns from script processing routine. Restores registers and returns. Entry: 8-bit A, 16-bit X/Y.
ReturnFromScript:
        PLD
        PLP
        PLB
        RTL
; [Entity] Checks entity state and position. Validates entity index bounds and state flags.
CheckEntityState:
        REP #$30
        TXA
        CLC
        ADC.W #$0022
        CMP.W #$18D4
        BEQ UnidentifiedFunction81C343
        TAX
        BRA CheckEntityCollisionLoop
; [Unknown] Function at $81C343 - needs analysis. Entry: 16-bit A/X/Y.
UnidentifiedFunction81C343:
        PLP
        RTS
; Processes graphics update routine. Entry: 8-bit A, 16-bit X/Y.
ProcessGraphicsUpdate:
        PHP
        REP #$10
        LDX.W #$1670
; [Collision] Main loop for entity collision detection processing.
CheckEntityCollisionLoop:
        SEP #$20
        LDA.W $0000,X
        BEQ CheckEntityState
        LDA.B $00
        BEQ CheckEntityState
        LDA.B #$00
        XBA
        LDA.W $000D,X
        ASL A
        TAY
        REP #$20
        LDA.B $02
        CLC
        ADC.W $C5E4,Y
        STA.B $70
        LDA.B $02
        SEC
        SBC.W $C5E4,Y
        STA.B $72
        LDA.B $05
        CLC
        ADC.W $C5E6,Y
        STA.B $74
        LDA.B $05
        SEC
        SBC.W $C5E6,Y
        STA.B $76
        SEP #$20
        LDA.W $000A,X
        BNE CheckEntityBehavior
        LDA.B $0A
        CMP.B #$30
        BNE CheckEntityType
        LDA.B $0B
        CMP.B #$04
        BEQ CheckEntityBehavior
        BRA HandleSpecialEntity
; [Entity] Checks entity type and calls appropriate handler. Tests for specific entity type values.
CheckEntityType:
        LDA.B $0A
        CMP.B #$06
        BNE CheckEntityBehavior
        LDA.B $0B
        BNE CheckEntityBehavior
; [Entity] Handles special entity type. Calls $C64E routine for special entity processing.
HandleSpecialEntity:
        REP #$30
        JSR.W CheckSpecialCollision
        BRA CheckEntityBehavior
; [Entity] Checks entity behavior flags and calls appropriate action routines.
CheckEntityBehavior:
        SEP #$20
        LDA.W $000A,X
        CMP.B #$08
        BEQ CallEntityAction
        CMP.B #$0C
        BEQ CallEntityAction
        CMP.B #$16
        BEQ CallEntityAction
        CMP.B #$1A
        BEQ CallEntityAction
        BRA ContinueEntityProcessing
; [Entity] Calls entity action routine at $C3C3 based on entity state.
CallEntityAction:
        JSR.W EntityActionDispatcher
; [Entity] Continues entity processing after action routine.
ContinueEntityProcessing:
        JMP.W CheckEntityState
; [Entity] Entity action dispatcher. Uses jump table at $C3D0 based on entity type in $0A.
EntityActionDispatcher:
        PHP
        SEP #$20
        PHX
        LDA.B #$00
        XBA
        LDA.B $0A
        TAX
        JMP.W ($C3D0,X)
        db $13,$C4,$13,$C4,$13,$C4,$13,$C4,$13,$C4,$13,$C4,$10,$C4,$10,$C4
        db $10,$C4,$13,$C4,$10,$C4,$10,$C4,$13,$C4,$10,$C4,$10,$C4
        db $10,$C4,$10,$C4
        db $10,$C4,$13,$C4,$13,$C4
        db $10,$C4,$13,$C4
        db $13,$C4
        db $10,$C4
        db $13,$C4,$13,$C4,$10,$C4
        db $10,$C4
        db $10,$C4
        db $13,$C4
        db $13,$C4
        db $13,$C4
        PLX
; [Collision] Returns from collision detection routine. Restores processor flags.
ReturnFromCollision:
        PLP
        RTS
        PLX
        LDA.B $AC
        BNE ReturnFromCollision
        REP #$20
        TDC
        CMP.W $0020,X
        BEQ ReturnFromCollision
        LDA.B $96
        BNE ReturnFromCollision
        LDA.B $CE
        BNE ReturnFromCollision
        LDA.W $0008,X
        SEC
        SBC.B $08
        BPL ReturnFromCollision
        LDA.W $0002,X
        CMP.B $70
        BCS ReturnFromCollision
        CMP.B $72
        BCC ReturnFromCollision
        LDA.W $0005,X
        CMP.B $74
        BCS ReturnFromCollision
        CMP.B $76
        BCC ReturnFromCollision
        SEP #$20
        LDA.W $000B,X
        EOR.B #$01
        STA.B $2A
        LDA.B #$00
        XBA
        LDA.W $000A,X
        CMP.B #$08
        BEQ CheckEntitySubtype
        CMP.B #$16
        BEQ CheckEntitySubtype
        CMP.B #$1A
        BNE CODE_41C46B
; [Entity] Checks entity subtype and branches to appropriate handler.
CheckEntitySubtype:
        LDA.W $000D,X
        CMP.B #$08
        BEQ CODE_41C472
        JMP.W ProcessEntityDamage
CODE_41C46B:
        LDA.W $000A,X
        CMP.B #$0C
        BNE CODE_41C475
CODE_41C472:
        JMP.W $C4ED
        db $28,$60
; [Entity] Processes entity damage/health. Checks health value and sets damage state if below threshold.
