; [Collision] Calculates entity collision bounds: B0/B2 from $02 ± [$70],Y, B4/B6 from $05+$08 ± [$70],Y
CalculateEntityBounds:
        REP #$20
        LDA.B $02
        CLC
        ADC.B [$70],Y
        STA.B $B2
        INY
        INY
        LDA.B $02
        SEC
        SBC.B [$70],Y
        STA.B $B0
; [Collision] Continues entity bounds calculation: increments Y, calculates B4/B6 bounds
CalculateEntityBounds2:
        INY
        INY
        LDA.B $05
        CLC
        ADC.B $08
        SEC
        SBC.B [$70],Y
        STA.B $B4
        INY
        INY
        LDA.B $05
        CLC
        ADC.B $08
        SEC
        ADC.B [$70],Y
        STA.B $B6
        PLP
        RTS
; [Collision] Calculates entity hitbox bounds based on $0010,X: B8/BA from $0002,X ± [$74],Y, BC/BE from $0005,X+$0008,X ± [$74],Y
CalculateEntityHitbox:
        PHP
        REP #$30
        LDA.W $0010,X
        AND.W #$00FF
        ASL A
        ASL A
        ASL A
        TAY
        SEP #$20
        LDA.W $002A,X
        BEQ CalculateHitboxRight
        REP #$20
        LDA.W $0002,X
        SEC
        SBC.B [$74],Y
        STA.B $B8
        INY
        INY
        LDA.W $0002,X
        CLC
        ADC.B [$74],Y
        STA.B $BA
        BRA CalculateHitboxTop
; [Collision] Calculates right hitbox bound BA from $0002,X + [$74],Y
CalculateHitboxRight:
        REP #$20
        LDA.W $0002,X
        CLC
        ADC.B [$74],Y
        STA.B $BA
        INY
        INY
        LDA.W $0002,X
        SEC
        SBC.B [$74],Y
        STA.B $B8
; [Collision] Calculates top hitbox bound BC from $0005,X+$0008,X - [$74],Y, minimum #$0001
CalculateHitboxTop:
        INY
        INY
        LDA.W $0005,X
        CLC
        ADC.W $0008,X
        SEC
        SBC.B [$74],Y
        BPL StoreHitboxTop
        LDA.W #$0001
; [Collision] Stores calculated top hitbox bound to $BC
StoreHitboxTop:
        STA.B $BC
        INY
        INY
        LDA.W $0005,X
        CLC
        ADC.W $0008,X
        SEC
        SBC.B [$74],Y
        BPL StoreHitboxBottom
        LDA.W #$0001
; [Collision] Stores calculated bottom hitbox bound to $BE
StoreHitboxBottom:
        STA.B $BE
        PLP
        RTS
