; [Entity] Sets up entity interaction: stores $58, sets $005D,X=#1E, $13F7=#01, checks entity state $0A, type $27
SetupEntityInteraction:
        PHP
        REP #$30
        TDC
        STA.W $0058,X
        TXA
        STA.B $58
        PHX
        SEP #$20
        LDA.B #$1E
        STA.W $005D,X
        LDA.B #$01
        STA.W $13F7
        LDA.B #$00
        XBA
        LDA.B $40
        REP #$20
        ASL A
        ASL A
        TAY
        SEP #$20
        LDA.W $000A,X
        CMP.B #$18
        BNE handleEntityTypeSpecificLogic
        JMP.W InitializeEntityState18
; [Entity] Handles entity type-specific logic and state transitions
handleEntityTypeSpecificLogic:
        LDA.W $0027,X
        CMP.B #$36
        BCC CheckEntityState0B06
        JMP.W CopyEntityTimerAE
; [Entity] Checks if $0B == #$06, $CE == 0, $F9 == 0, sets $F9=#03, calls $81E134 with #$0003
CheckEntityState0B06:
        LDA.B $0B
        CMP.B #$06
        BNE CheckEntityType22
        REP #$20
        LDA.B $CE
        BNE CheckEntityType22
        SEP #$20
        LDA.B $F9
        BNE CheckEntityType22
        LDA.B #$03
        STA.B $F9
        REP #$20
        LDA.W #$0003
