; [Entity] Checks if entity type $27 == #$22, sets $00F9,X = #$1F if $00F9,X == 0
CheckEntityType22:
        SEP #$20
        LDA.W $0027,X
        CMP.B #$22
        BNE LoadEntityIndex42
        LDA.W $00F9,X
        BNE LoadEntityIndex42
        LDA.B #$1F
        STA.W $00F9,X
; [Entity] Loads entity index from $42, multiplies by 2 for table lookup
LoadEntityIndex42:
