        db $16,$CD
        db $DB,$CD,$DB,$CD
; [Entity] Initializes entity state for $0A=#18: clears $11-$15,X, calls $DC9E, checks $CE32,Y, $CE31,Y, sets $13F7=#01, $000B,X=#02
InitializeEntityState18:
        REP #$30
        PLX
        STZ.W $0011,X
        STZ.W $0013,X
        STZ.W $0015,X
        JSR.W ProcessAudioVolumeFromAE
        SEP #$20
        LDA.W $CE32,Y
        BEQ CheckEntityFlagCE31
        db $C2,$20,$9C,$00,$00,$A9,$50,$00,$8D,$02,$00,$22,$2F,$DC,$81,$22
        db $45,$E1,$81
; [Entity] Checks $CE31,Y flag, toggles $2A and stores to $002A,X if non-zero
CheckEntityFlagCE31:
        SEP #$20
        LDA.W $CE31,Y
        BEQ SetEntityState01
        db $A5,$2A,$49,$01,$9D,$2A,$00
; [Entity] Sets entity state: $13F7=#01, $000B,X=#02
SetEntityState01:
        LDA.B #$01
        STA.W $13F7
        LDA.B #$02
        STA.W $000B,X
        REP #$20
        LDA.B $12
        STA.W $0032,X
        SEP #$20
        LDA.B $0B
        CMP.B #$04
        BCS LoadEntityFlagAC
        LDA.B $0B
        BNE InitEntityWithFlagAC
