; [Entity] Initializes entity: sets $0B=2, $46=$38, loads entity flag $AC from table $CC98 based on $42. Entry: 8-bit A, 16-bit X/Y.
InitEntityWithFlagAC:
        LDA.B #$02
        STA.B $0B
        LDA.B #$38
        STA.B $46
; [Entity] Loads entity flag $AC from table $CC98 based on $42, stores to $00AC,X
LoadEntityFlagAC:
