        RTS
; [Music] Sets up entity audio: stores $00AE,X to $1288, $0002,X to $128A, calls CalculateAudioVolume, sets entity state $0A=#$063C, $0C=0, $A0=#$10, $AC=#$10, calls $CDC0
SetupEntityAudio:
