        REP #$30
        PLX
        JSL.L AddToEntityPosition
        SEP #$20
        LDA.B $40
        CMP.B #$10
        BNE checkEntityPosition
        db $BD,$0A,$00,$C9,$10,$D0,$03,$4C,$EF,$CD
; [Entity] Checks entity position and handles negative position cases
checkEntityPosition:
