        SBC.W #$0008
        STA.B $B0
; [Collision] Checks entity collision with bounds at $B4/$B6 (X) and $B0/$B2 (Y). Sets collision state $B0 to 0x0D or 0x0E based on $2A. Calls handleEntityInteraction if collision detected. Entry: 16-bit A/X/Y.
checkEntityCollision:
