EarlyExitFromCheck:
        PLP
        PLB
        RTL
; [Entity] Checks multiple game conditions for entity processing. Early exits if any condition fails.
CheckEntityConditions:
        PHB
        PHP
        PHK
        PLB
        REP #$20
        LDA.B $CE
        BNE ProcessSpecialEntityCase
        SEP #$20
        LDA.W $1E8D
        BNE EarlyExitFromCheck
        REP #$10
        LDA.B $2E
        BNE EarlyExitFromCheck
        LDA.B $27
