        REP #$20
        LDA.B $94
        SEC
        SBC.B $96
        BMI EarlyExitFromCheck
        LDA.B $CC
        CMP.W #$003F
        BCC ExitAfterEntityCheck
        JSL.L CheckSpecialEntityTypes
; [Helper] Exit point after entity condition checks - restores flags and returns.
ExitAfterEntityCheck:
        PLP
        PLB
        RTL
; [Entity] Processes special entity case when $CE is non-zero. Calculates offset based on $24 value.
ProcessSpecialEntityCase:
        REP #$30
