        LDA.B $27
        AND.W #$00FF
        TAX
        LDA.W $E08A,X
        TAX
        LDA.W #$001F
        PHB
        MVN $00,$C0
        BRA CleanupMemoryCopy
; [Memory] Copies memory block using MVN. Uses $27 as index into table at $82958A to get transfer length. Entry: 16-bit A/X/Y.
CopyMemoryBlock:
        LDA.B $27
        AND.W #$00FF
        TAX
        LDA.L $82958A,X
        TAX
        LDA.W #$001F
        PHB
        MVN $00,$7E
